(()=>{const want=['IBM Plex Sans','IBM Plex Sans Condensed','IBM Plex Mono'];
const loaded=want.map(f=>({family:f,loaded:document.fonts.check('16px "'+f+'"')}));
const h=document.querySelector('h1');const cs=getComputedStyle(h);
return JSON.stringify({fonts:loaded,h1Font:cs.fontFamily,h1Size:cs.fontSize,bodyBg:getComputedStyle(document.body).backgroundColor,
tables:document.querySelectorAll('table').length,mapTables:document.querySelectorAll('.mapdoc table').length,
sections:document.querySelectorAll('section').length,docHeight:document.documentElement.scrollHeight,
scrollW:document.documentElement.scrollWidth,clientW:document.documentElement.clientWidth})})()

